ruleToc.chapterList:
+@js:JSON.parse(result).chapterlist.map((x,y)=>{
	a=x.chaptertype==0;
	b=x.chaptername;
	c=x.islock==0;
	d=x.chapterid;
	v=x.isvip!=0;

/**/n=(a?+d+'｜':'')+b//卷名
//n=(a?d+'｜'+b:'')//无卷名
+(a&&!c?'[锁]':'');

u=(a&&c?v?'http://my.jjwxc.net/onebook_vip':'http://www.jjwxc.net/onebook':'http://:')+(a&&c?'.php?novelid='+x.novelid+'&chapterid='+d:('0000'+y).slice(-5)+'-'+java.md5Encode16(n));

v=a&&v?'❍·':'';

i=a?x.chapterdate+'•'+x.chaptersize+'字'+'•'+x.chapterintro:'☆'.repeat(b.length);
return{
       n:v+n,
       u:u,
       i:i
}
})
